1	package payflow
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	// 本文件回归“初始化后、首次打开之前”的文件权威语义：
11	//
12	// CreateLedger 成功只代表磁盘上曾写入一份完整账本，绝不代替首次 Open
13	// 对该路径当前内容的检查。若尚无句柄，文件被删除、清空、截断或改成
14	// 校验和不匹配的内容，首次 Open 必须如实返回 ledger_not_initialized 或
15	// corrupt_ledger，且不返回句柄、不重新生成账本、不恢复初始余额或修补文件。
16	//
17	// 同一路径重新放回合法账本后，再次 Open 读到的是该文件此刻的内容。
18	
19	// writeFileAt 用给定内容覆盖 path（文件不存在时创建）。
20	func writeFileAt(t *testing.T, path string, data []byte) {
21		t.Helper()
22		if err := os.WriteFile(path, data, 0o600); err != nil {
23			t.Fatalf("write %s: %v", path, err)
24		}
25	}
26	
27	// assertOpenFails 断言 Open 返回指定错误分类、句柄为 nil，且不留下任何
28	// 会让后续 Open 跳过读盘的内存状态。
29	func assertOpenFails(t *testing.T, path, wantKind string) {
30		t.Helper()
31		l, err := Open(path)
32		if l != nil {
33			_ = l.Close()
34			t.Fatalf("Open on bad ledger must not return a usable handle, got %+v", l)
35		}
36		if KindOf(err) != wantKind {
37			t.Fatalf("Open: want %s, got %v", wantKind, err)
38		}
39	}
40	
41	// 初始化后尚无任何句柄：删除文件，首次 Open 必须报 ledger_not_initialized，
42	// 且不得（重新）生成账本文件。
43	func TestFirstOpenAfterFileDeletedIsNotInitialized(t *testing.T) {
44		path := newTestLedger(t, []BalanceInit{
45			{Account: "aa", Asset: "usdc", Balance: 500},
46			{Account: "aa", Asset: "eth", Balance: 3},
47		})
48		if err := os.Remove(path); err != nil {
49			t.Fatal(err)
50		}
51	
52		assertOpenFails(t, path, ErrNotInit)
53		// 失败不得重新生成账本。
54		if _, err := os.Stat(path); !os.IsNotExist(err) {
55			t.Fatalf("failed open must not recreate the ledger file, stat err=%v", err)
56		}
57		// 再试一次仍按磁盘现状报未初始化：失败结果不得被缓存成“已初始化”。
58		assertOpenFails(t, path, ErrNotInit)
59	}
60	
61	// 初始化后尚无任何句柄：把刚创建账本自身的文件清空、只留白字符或截断成
62	// 半个 JSON，首次 Open 必须报 corrupt_ledger，且原字节不得被修补或覆盖。
63	func TestFirstOpenOnEmptyOrTruncatedFileIsCorrupt(t *testing.T) {
64		cases := map[string]func(raw []byte) []byte{
65			"empty":          func(raw []byte) []byte { return nil },
66			"whitespace":     func(raw []byte) []byte { return []byte("   \n\t  ") },
67			"truncated json": func(raw []byte) []byte { return raw[:len(raw)/2] },
68			"open brace":     func(raw []byte) []byte { return []byte("{") },
69		}
70		for name, mutate := range cases {
71			t.Run(name, func(t *testing.T) {
72				// 每个子用例用各自刚创建的账本，并篡改“同一个路径”。
73				path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
74				raw, err := os.ReadFile(path)
75				if err != nil {
76					t.Fatal(err)
77				}
78				content := mutate(raw)
79				writeFileAt(t, path, content)
80	
81				assertOpenFails(t, path, ErrCorrupt)
82	
83				after, statErr := os.ReadFile(path)
84				if statErr != nil {
85					t.Fatalf("failed open must not remove the file: %v", statErr)
86				}
87				if !bytes.Equal(content, after) {
88					t.Fatalf("failed open must not repair/rewrite the file")
89				}
90			})
91		}
92	}
93	
94	// 初始化后尚无任何句柄：把刚创建账本自身的文件改成校验和不匹配的内容
95	// （比特翻转或语义编辑），首次 Open 必须报 corrupt_ledger，且文件逐字节不变。
96	func TestFirstOpenOnChecksumMismatchIsCorrupt(t *testing.T) {
97		cases := map[string]func(b []byte) []byte{
98			"bitflip": func(b []byte) []byte {
99				b[10] ^= 0x01
100				return b
101			},
102			"semantic edit": func(b []byte) []byte {
103				return bytes.ReplaceAll(b, []byte(`"balance":500`), []byte(`"balance":999`))
104			},
105		}
106		for name, mutate := range cases {
107			t.Run(name, func(t *testing.T) {
108				path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
109				raw, err := os.ReadFile(path)
110				if err != nil {
111					t.Fatal(err)
112				}
113				content := mutate(bytes.Clone(raw))
114				writeFileAt(t, path, content)
115	
116				assertOpenFails(t, path, ErrCorrupt)
117	
118				after, err := os.ReadFile(path)
119				if err != nil {
120					t.Fatal(err)
121				}
122				if !bytes.Equal(after, content) {
123					t.Fatalf("failed open must leave the corrupt file byte-intact")
124				}
125			})
126		}
127	}
128	
129	// 完好文件上的首次打开：得到初始化时的账户、资产与金额；读取本身不改文件。
130	func TestFirstOpenOnIntactFileReadsInitStateWithoutWriting(t *testing.T) {
131		path := newTestLedger(t, []BalanceInit{
132			{Account: "aa", Asset: "usdc", Balance: 500},
133			{Account: "bb", Asset: "eth", Balance: 7},
134		})
135		before, err := os.ReadFile(path)
136		if err != nil {
137			t.Fatal(err)
138		}
139	
140		l, err := Open(path)
141		if err != nil {
142			t.Fatalf("first open on intact file: %v", err)
143		}
144		// 打开后只查询，不提交任何业务操作。
145		snap, err := l.Query()
146		if err != nil {
147			t.Fatal(err)
148		}
149		if len(snap.Settlements) != 0 || len(snap.Refunds) != 0 {
150			t.Fatalf("fresh ledger must have empty history: %+v", snap)
151		}
152		if got := len(snap.Balances); got != 2 {
153			t.Fatalf("balances=%+v want 2 initial combos", snap.Balances)
154		}
155		for _, want := range []BalanceView{
156			{Account: "aa", Asset: "usdc", Balance: 500},
157			{Account: "bb", Asset: "eth", Balance: 7},
158		} {
159			bal, err := l.Balance(want.Account, want.Asset)
160			if err != nil {
161				t.Fatal(err)
162			}
163			if bal != want.Balance {
164				t.Fatalf("%s/%s balance=%d want %d", want.Account, want.Asset, bal, want.Balance)
165			}
166		}
167		if err := l.Close(); err != nil {
168			t.Fatal(err)
169		}
170	
171		after, err := os.ReadFile(path)
172		if err != nil {
173			t.Fatal(err)
174		}
175		if !bytes.Equal(before, after) {
176			t.Fatalf("first open/query must not modify the ledger file")
177		}
178	}
179	
180	// 失败的打开不污染后续使用：同一目录路径先放回一份与初始化余额不同的
181	// 合法账本，再次 Open 必须读到新文件内容，而不是初始化时的旧余额或
182	// 沿用上一次错误。
183	func TestFailedFirstOpenRecoversWhenValidFileRestored(t *testing.T) {
184		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
185	
186		// 删除 → 未初始化。
187		if err := os.Remove(path); err != nil {
188			t.Fatal(err)
189		}
190		assertOpenFails(t, path, ErrNotInit)
191	
192		// 放回一份余额完全不同（900、带一笔付款记录）的合法账本：用库自身
193		// 在另一个路径生成，再移动到原路径，保证校验和完整。
194		replacement := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
195		rl, err := Open(replacement)
196		if err != nil {
197			t.Fatal(err)
198		}
199		if _, err := rl.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
200			intent("restored-pay", "aa", "usdc", 100),
201		}}); err != nil {
202			t.Fatal(err)
203		}
204		if err := rl.Close(); err != nil {
205			t.Fatal(err)
206		}
207		restored, err := os.ReadFile(replacement)
208		if err != nil {
209			t.Fatal(err)
210		}
211		writeFileAt(t, path, restored)
212	
213		l, err := Open(path)
214		if err != nil {
215			t.Fatalf("reopen after restoring a valid file: %v", err)
216		}
217		if bal, _ := l.Balance("aa", "usdc"); bal != 900 {
218			t.Fatalf("reopen must read the restored file, balance=%d want 900", bal)
219		}
220		snap, _ := l.Query()
221		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "restored-pay" {
222			t.Fatalf("reopen must read the restored file's history: %+v", snap.Settlements)
223		}
224		if err := l.Close(); err != nil {
225			t.Fatal(err)
226		}
227	
228		// 恢复后若文件再次被损坏，由于已无活动句柄，Open 必须重新以磁盘为准
229		// 报损坏，而不是沿用上一次成功读到的 900 余额。
230		tampered := bytes.Clone(restored)
231		tampered[10] ^= 0x01
232		writeFileAt(t, path, tampered)
233		assertOpenFails(t, path, ErrCorrupt)
234	}
235	
236	// 损坏与未初始化必须可区分：同一路径上“文件缺失”与“文件为空”分别
237	// 返回 ledger_not_initialized 与 corrupt_ledger，绝不能都表现成空余额/
238	// 空历史的正常账本。
239	func TestMissingAndCorruptAreDistinguishableOnFirstOpen(t *testing.T) {
240		missing := filepath.Join(t.TempDir(), "missing.json")
241		if _, err := Open(missing); KindOf(err) != ErrNotInit {
242			t.Fatalf("missing: want %s, got %v", ErrNotInit, err)
243		}
