394		var doc signedDoc
395		if err := json.Unmarshal(raw, &doc); err != nil {
396			t.Fatalf("on-disk JSON invalid: %v\n%s", err, raw)
397		}
398		if doc.Version != 1 {
399			t.Fatalf("version=%d", doc.Version)
400		}
401		if len(doc.Initial) != 1 || doc.Initial[0].Balance != 10 {
402			t.Fatalf("initial balances on disk: %+v", doc.Initial)
403		}
404		if len(doc.Balances) != 1 || doc.Balances[0].Balance != 0 || len(doc.Settlements) != 1 {
