1330		// 退回的 1000 余额上并发发起 40 笔各 1000 的付款：恰有一笔成功。
1331		const n = 40
1332		var wg sync.WaitGroup
1333		c := map[string]int{}
1334		var mu sync.Mutex
1335		for i := 0; i < n; i++ {
1336			i := i
1337			wg.Add(1)
