1348				}})
1349				if err != nil {
1350					t.Errorf("Submit: %v", err)
1351					return
1352				}
1353				mu.Lock()
1354				c[res.Results[0].Status]++
1355				mu.Unlock()
1356			}()
1357		}
1358		wg.Wait()
1359		if c[StatusSettled] != 1 || c[StatusFunds] != n-1 {
1360			t.Fatalf("counts=%v want exactly 1 settled", c)
1361		}
1362		if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
1363			t.Fatalf("balance=%d want 0", bal)
1364		}
1365	}
