		snap2.Refunds[0].ID != "r1" || snap2.Refunds[0].SettlementID != "p1" ||
		snap2.Refunds[0].AfterSeq != 1 {
		t.Fatalf("reopen history not preserved: %+v / %+v", snap2.Settlements, snap2.Refunds)
	}
